function teacherCard(o){const bugun=todayLessons(o.id).length,duty=dutiesOf(o.id).length,phone=o.telefon||'';return `<article class="ka-card ka-teacher-card"><div class="ka-card__body"><div class="ka-row"><span class="ka-teacher-avatar">${esc(initials(o))}</span><div class="ka-grow"><h3>${esc(fullName(o))}</h3><strong class="ka-teacher-branch">${esc(o.brans||o.unvan||'Öğretmen')}</strong></div><button class="ka-icon-button ka-teacher-arrow" type="button" data-teacher-detail="${esc(o.id)}" aria-label="Profil ayrıntısı">›</button></div><div class="ka-teacher-chips"><span class="ka-badge">${bugun?`Bugün ${bugun} ders`:'Bugün dersi yok'}</span>${duty?`<span class="ka-badge ka-badge--warning">Nöbet kaydı</span>`:''}</div><div class="ka-teacher-meta"><span>Haftalık ${weeklyHours(o.id)} ders saati</span>${phone?`<a href="tel:${esc(phone)}">${esc(phone)}</a>`:''}</div><div class="ka-teacher-actions"><button class="ka-btn ka-btn--secondary" type="button" data-teacher-detail="${esc(o.id)}">Profili Gör</button>${canEdit()?`<button class="ka-btn ka-btn--secondary" type="button" data-teacher-edit="${esc(o.id)}">Düzenle</button>`:''}</div></div></article>`}
